    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 68-year-old male presents with severe back pain. Radiographs of the lumbar spine show a dense, sclerotic (osteoblastic) lesion in the L3 vertebral body. Laboratory studies show an elevated alkaline phosphatase, but normal calcium. Which primary malignancy is most likely responsible for this metastatic lesion?', '["Malignant melanoma", "Prostate carcinoma", "Renal cell carcinoma", "Thyroid carcinoma", "Multiple myeloma"]'::jsonb, 1, 'Metastatic prostate cancer characteristically produces osteoblastic (sclerotic) bone lesions due to the secretion of factors that stimulate bone formation (like BMPs). Conversely, cancers like renal cell, thyroid, and multiple myeloma typically cause osteolytic (destructive) lesions.'),
    (v_topic_id, 'A 14-year-old child presents with a 1-month history of fever, localized pain, and swelling over the mid-shaft of the femur. Labs show an elevated ESR and leukocytosis. Radiographs demonstrate a permeative, lytic lesion in the diaphysis with a multilamellated ''onion-skin'' periosteal reaction. Which chromosomal translocation is most characteristically associated with this diagnosis?', '["t(8;14)", "t(X;18)", "t(14;18)", "t(9;22)", "t(11;22)"]'::jsonb, 4, 'Ewing sarcoma often mimics osteomyelitis clinically (fever, elevated inflammatory markers). It occurs in the diaphysis of long bones. It is a small round blue cell tumor strongly associated with the t(11;22) translocation, resulting in the EWS-FLI1 fusion protein. CD99 is typically strongly positive.'),
    (v_topic_id, 'A 63-year-old male presents with severe back pain. Radiographs of the lumbar spine show a dense, sclerotic (osteoblastic) lesion in the L3 vertebral body. Laboratory studies show an elevated alkaline phosphatase, but normal calcium. Which primary malignancy is most likely responsible for this metastatic lesion?', '["Multiple myeloma", "Thyroid carcinoma", "Renal cell carcinoma", "Malignant melanoma", "Prostate carcinoma"]'::jsonb, 4, 'Metastatic prostate cancer characteristically produces osteoblastic (sclerotic) bone lesions due to the secretion of factors that stimulate bone formation (like BMPs). Conversely, cancers like renal cell, thyroid, and multiple myeloma typically cause osteolytic (destructive) lesions.'),
    (v_topic_id, 'A 71-year-old female with a history of breast cancer presents with a pathologic fracture of the proximal pelvis. The lesion is lytic. What is the primary goal of orthopedic stabilization in this setting?', '["Achieving a biologic union of the fracture site without cement", "Curative resection of the tumor with wide margins", "Delaying surgery until radiation therapy is completed", "Immediate pain relief, early mobilization, and restoration of function", "Preventing pulmonary metastasis"]'::jsonb, 3, 'The treatment of metastatic pathologic fractures is generally palliative. The goals are to provide immediate mechanical stability (often using intramedullary nails and cement), relieve pain, and allow early weight-bearing and functional independence.'),
    (v_topic_id, 'A 10-year-old child presents with a limp. Radiographs of the proximal femur show a ''shepherd''''s crook'' deformity with an intramedullary lesion demonstrating a ''ground-glass'' appearance. The patient also has large, irregular cafe-au-lait spots with ''coast of Maine'' borders. What other clinical feature might this patient exhibit?', '["Precocious puberty", "Hearing loss and cranial nerve palsies", "Axillary freckling and Lisch nodules", "Retinal hemangioblastomas", "Multiple lipomas"]'::jsonb, 0, 'McCune-Albright syndrome consists of the triad of polyostotic fibrous dysplasia (ground-glass bone lesions, shepherd''''s crook deformity), café-au-lait macules with irregular borders (coast of Maine), and endocrine abnormalities (most commonly precocious puberty). It is caused by an activating mutation in the GNAS gene.'),
    (v_topic_id, 'A 6-year-old boy falls and sustains a pathologic fracture of the proximal humerus. Radiographs show a centrally located, lytic lesion in the metaphysis that is well-marginated. A fragment of cortical bone is seen resting at the bottom of the cystic cavity. What is the most likely diagnosis?', '["Non-ossifying fibroma", "Unicameral (Simple) Bone Cyst", "Fibrous dysplasia", "Osteosarcoma", "Aneurysmal Bone Cyst"]'::jsonb, 1, 'The ''''fallen leaf'''' or ''''fallen fragment'''' sign is pathognomonic for a Unicameral Bone Cyst (UBC). When a pathologic fracture occurs, a piece of cortical bone breaks off and sinks through the serous fluid to the bottom of the cyst. An ABC would be eccentric, expansile, and contain blood.'),
    (v_topic_id, 'A 23-year-old patient presents with a swollen, deformed hand. Radiographs show multiple centrally located radiolucent lesions with stippled calcifications within the phalanges and metacarpals. Physical exam reveals multiple soft tissue hemangiomas on the same limb. What is the diagnosis?', '["McCune-Albright syndrome", "Multiple hereditary exostoses", "Neurofibromatosis type 1", "Ollier disease", "Maffucci syndrome"]'::jsonb, 4, 'Enchondromas are benign cartilage tumors of the medullary cavity, frequently found in the small bones of the hands and feet. Multiple enchondromas alone characterize Ollier disease. When multiple enchondromas are accompanied by soft tissue hemangiomas, it is called Maffucci syndrome, which carries a much higher risk of malignant transformation to chondrosarcoma and other visceral malignancies.'),
    (v_topic_id, 'A 16-year-old female presents with pain and swelling in the distal femur. Imaging shows an eccentric, expansile, lytic metaphyseal lesion. An MRI reveals multiple fluid-fluid levels within the lesion. Histology shows blood-filled spaces lacking an endothelial lining. What is the most likely diagnosis?', '["Chondroblastoma", "Unicameral Bone Cyst (UBC)", "Telangiectatic Osteosarcoma", "Aneurysmal Bone Cyst (ABC)", "Giant Cell Tumor"]'::jsonb, 3, 'Aneurysmal bone cysts (ABCs) are expansile, blood-filled cystic lesions. The classic MRI finding is ''''fluid-fluid levels'''' representing separation of serum and red blood cells. Treatment often involves extended curettage, high-speed burring, and bone grafting.'),
    (v_topic_id, 'A 72-year-old patient complains of severe pain in the tibia. Imaging shows a ''punched-out'' lytic lesion. Blood work reveals anemia, hypercalcemia, and renal insufficiency. A serum protein electrophoresis (SPEP) is ordered. What is the expected mechanism of the bone destruction?', '["Osteoblast overactivation", "Ischemic necrosis of the medullary cavity", "Deposition of amyloid protein in the bone matrix", "Neoplastic plasma cells secrete factors (like MIP-1 alpha and RANKL) that stimulate osteoclasts.", "Direct mechanical pressure from the tumor mass"]'::jsonb, 3, 'In multiple myeloma, malignant plasma cells upregulate osteoclast activity (via RANKL and MIP-1 alpha) and downregulate osteoblast activity (via DKK-1), leading to pure lytic lesions without reactive new bone formation.'),
    (v_topic_id, 'A 6-year-old patient is diagnosed with high-grade conventional osteosarcoma of the distal femur. They are scheduled for a limb-salvage procedure. According to standard protocol, what must precede the surgical resection?', '["Bisphosphonates", "Amputation", "Radiation therapy", "Denosumab", "Neoadjuvant chemotherapy"]'::jsonb, 4, 'Standard treatment for high-grade osteosarcoma includes neoadjuvant (preoperative) chemotherapy, which targets micrometastases and shrinks the tumor, followed by wide surgical resection and adjuvant chemotherapy.'),
    (v_topic_id, 'A 74-year-old patient presents with a slowly worsening ache in the pelvis. Radiographs show a large, poorly defined intramedullary lesion with endosteal scalloping and prominent ''popcorn'' or ''ring-and-arc'' calcifications. Biopsy confirms malignant cartilage. What is the primary modality of treatment?', '["Denosumab therapy", "High-dose radiation therapy", "Wide surgical resection", "Systemic chemotherapy", "Radiofrequency ablation"]'::jsonb, 2, 'Chondrosarcomas are malignant tumors of cartilage typically seen in older adults (pelvis, proximal femur). They are notoriously resistant to both chemotherapy and radiation therapy. Therefore, wide surgical excision is the mainstay of treatment for conventional chondrosarcomas.'),
    (v_topic_id, 'A 10-year-old patient presents with rapid swelling of the pelvis. Radiographs show an eccentric, expansile metaphyseal lesion. MRI shows multiple fluid-fluid levels. What does this MRI finding represent?', '["Pus settling from an abscess", "Fat floating on water within a lipoma", "Contrast pooling in a hemangioma", "Separation of cellular blood components from serum", "Necrotic tumor debris"]'::jsonb, 3, 'The ''''fluid-fluid level'''' on MRI in an aneurysmal bone cyst (ABC) represents the settling of red blood cells out of serum in the cyst''''s cavernous, blood-filled spaces.'),
    (v_topic_id, 'A 49-year-old female with a history of breast cancer presents with a pathologic fracture of the proximal femur. The lesion is lytic. What is the primary goal of orthopedic stabilization in this setting?', '["Curative resection of the tumor with wide margins", "Achieving a biologic union of the fracture site without cement", "Preventing pulmonary metastasis", "Delaying surgery until radiation therapy is completed", "Immediate pain relief, early mobilization, and restoration of function"]'::jsonb, 4, 'The treatment of metastatic pathologic fractures is generally palliative. The goals are to provide immediate mechanical stability (often using intramedullary nails and cement), relieve pain, and allow early weight-bearing and functional independence.'),
    (v_topic_id, 'A 23-year-old patient has intense nocturnal pain in the pelvis that responds dramatically to naproxen. Imaging confirms a nidus with surrounding sclerosis. If the patient opts for minimally invasive intervention, what is the treatment of choice?', '["Intra-articular steroid injection", "CT-guided radiofrequency ablation (RFA)", "Open en bloc resection", "Cryoablation without imaging", "Radiation therapy"]'::jsonb, 1, 'Osteoid osteomas are benign bone-forming tumors. While they can ''''burn out'''' spontaneously over years, symptomatic patients who cannot tolerate long-term NSAIDs are best treated with percutaneous, CT-guided radiofrequency ablation, which has a very high success rate.'),
    (v_topic_id, 'A 52-year-old patient complains of severe pain in the radius. Imaging shows a ''punched-out'' lytic lesion. Blood work reveals anemia, hypercalcemia, and renal insufficiency. A serum protein electrophoresis (SPEP) is ordered. What is the expected mechanism of the bone destruction?', '["Deposition of amyloid protein in the bone matrix", "Neoplastic plasma cells secrete factors (like MIP-1 alpha and RANKL) that stimulate osteoclasts.", "Ischemic necrosis of the medullary cavity", "Osteoblast overactivation", "Direct mechanical pressure from the tumor mass"]'::jsonb, 1, 'In multiple myeloma, malignant plasma cells upregulate osteoclast activity (via RANKL and MIP-1 alpha) and downregulate osteoblast activity (via DKK-1), leading to pure lytic lesions without reactive new bone formation.'),
    (v_topic_id, 'A 40-year-old patient presents with knee pain. Radiographs reveal an eccentric, expansile, lytic lesion resembling a ''soap bubble'' in the epiphysis of the distal femur extending to the subchondral bone. Biopsy shows mononuclear cells and numerous multinucleated giant cells. Which targeted systemic therapy can be used as an adjunct for large, unresectable, or recurrent lesions?', '["Imatinib (Tyrosine kinase inhibitor)", "Infliximab (TNF-alpha inhibitor)", "Methotrexate", "Rituximab (Anti-CD20)", "Denosumab (RANKL inhibitor)"]'::jsonb, 4, 'Giant Cell Tumor of bone classically occurs in skeletally mature individuals (epiphysis/metaphysis). The neoplastic mononuclear stromal cells express RANKL, which recruits and activates the multinucleated osteoclast-like giant cells. Denosumab, a monoclonal antibody against RANKL, is an effective targeted therapy.'),
    (v_topic_id, 'A 40-year-old patient requires an open incisional biopsy for a suspected high-grade soft tissue sarcoma of the anterior thigh. Which of the following is a critical principle when performing this biopsy?', '["Exsanguinate the limb with an Esmarch bandage before inflating the tourniquet", "Use a longitudinal incision placed within the planned definitive resection ellipse", "Dissect extensively through intermuscular planes to avoid muscle damage", "Use a transverse incision parallel to skin tension lines for a better cosmetic result", "Obtain a small sample of the necrotic center rather than the periphery to ensure a diagnosis"]'::jsonb, 1, 'Orthopedic oncology biopsy principles: 1) Longitudinal incisions (transverse incisions contaminate more tissue longitudinally). 2) The biopsy tract must be excisable en bloc with the tumor. 3) Avoid spreading through fascial planes (split muscle instead). 4) Do NOT exsanguinate with an Esmarch to prevent pushing tumor cells centrally. 5) Biopsy the periphery (the advancing edge), as the center is often necrotic.'),
    (v_topic_id, 'A 12-year-old child presents with a limp. Radiographs of the proximal femur show a ''shepherd''''s crook'' deformity with an intramedullary lesion demonstrating a ''ground-glass'' appearance. The patient also has large, irregular cafe-au-lait spots with ''coast of Maine'' borders. What other clinical feature might this patient exhibit?', '["Axillary freckling and Lisch nodules", "Hearing loss and cranial nerve palsies", "Retinal hemangioblastomas", "Multiple lipomas", "Precocious puberty"]'::jsonb, 4, 'McCune-Albright syndrome consists of the triad of polyostotic fibrous dysplasia (ground-glass bone lesions, shepherd''''s crook deformity), café-au-lait macules with irregular borders (coast of Maine), and endocrine abnormalities (most commonly precocious puberty). It is caused by an activating mutation in the GNAS gene.'),
    (v_topic_id, 'A 82-year-old patient presents with back pain and fatigue. Radiographs of the skull and spine show multiple ''punched-out'' radiolucencies without any surrounding reactive sclerosis. Laboratory tests reveal hypercalcemia, anemia, and an M-spike on serum protein electrophoresis. Which bone scan finding is expected?', '["Diffuse periosteal uptake", "Intensely increased uptake (''hot'' spots) in all lesions", "A ''superscan'' with absent renal visualization", "Increased uptake exclusively in the appendicular skeleton", "A falsely negative (''cold'' or normal) bone scan"]'::jsonb, 4, 'Multiple myeloma lesions are purely osteolytic, caused by myeloma cells stimulating osteoclasts (via RANKL) and actively inhibiting osteoblasts (via DKK-1). Because a Technetium-99m bone scan relies on osteoblastic activity (bone formation), it is notoriously unreliable (falsely negative) in multiple myeloma. A skeletal survey (plain films) or low-dose whole-body CT is the preferred imaging modality.'),
    (v_topic_id, 'A 70-year-old patient presents with a slowly worsening ache in the proximal femur. Radiographs show a large, poorly defined intramedullary lesion with endosteal scalloping and prominent ''popcorn'' or ''ring-and-arc'' calcifications. Biopsy confirms malignant cartilage. What is the primary modality of treatment?', '["Wide surgical resection", "Radiofrequency ablation", "High-dose radiation therapy", "Systemic chemotherapy", "Denosumab therapy"]'::jsonb, 0, 'Chondrosarcomas are malignant tumors of cartilage typically seen in older adults (pelvis, proximal femur). They are notoriously resistant to both chemotherapy and radiation therapy. Therefore, wide surgical excision is the mainstay of treatment for conventional chondrosarcomas.'),
    (v_topic_id, 'A 18-year-old patient has intense nocturnal pain in the radius that responds dramatically to naproxen. Imaging confirms a nidus with surrounding sclerosis. If the patient opts for minimally invasive intervention, what is the treatment of choice?', '["Radiation therapy", "Cryoablation without imaging", "Open en bloc resection", "CT-guided radiofrequency ablation (RFA)", "Intra-articular steroid injection"]'::jsonb, 3, 'Osteoid osteomas are benign bone-forming tumors. While they can ''''burn out'''' spontaneously over years, symptomatic patients who cannot tolerate long-term NSAIDs are best treated with percutaneous, CT-guided radiofrequency ablation, which has a very high success rate.'),
    (v_topic_id, 'A 22-year-old male presents with deep, aching pain in the posterior spine that is characteristically worse at night. The pain is completely relieved by ibuprofen. Radiographs show a small (< 1.5 cm) radiolucent nidus surrounded by dense reactive sclerosis. What is the most appropriate definitive management if symptoms become refractory?', '["Intravenous bisphosphonates", "Radiofrequency ablation (RFA)", "Radiation therapy", "Curettage and bone grafting", "Chemotherapy followed by limb-salvage surgery"]'::jsonb, 1, 'Osteoid osteoma classically presents with night pain relieved by NSAIDs due to high prostaglandin (PGE2) production by the tumor nidus. CT is the best imaging modality to visualize the nidus. If medical management fails or is poorly tolerated, percutaneous radiofrequency ablation (RFA) is the treatment of choice.'),
    (v_topic_id, 'A 53-year-old patient complains of severe pain in the humerus. Imaging shows a ''punched-out'' lytic lesion. Blood work reveals anemia, hypercalcemia, and renal insufficiency. A serum protein electrophoresis (SPEP) is ordered. What is the expected mechanism of the bone destruction?', '["Osteoblast overactivation", "Direct mechanical pressure from the tumor mass", "Neoplastic plasma cells secrete factors (like MIP-1 alpha and RANKL) that stimulate osteoclasts.", "Ischemic necrosis of the medullary cavity", "Deposition of amyloid protein in the bone matrix"]'::jsonb, 2, 'In multiple myeloma, malignant plasma cells upregulate osteoclast activity (via RANKL and MIP-1 alpha) and downregulate osteoblast activity (via DKK-1), leading to pure lytic lesions without reactive new bone formation.'),
    (v_topic_id, 'A 67-year-old female with a history of breast cancer presents with a pathologic fracture of the proximal humerus. The lesion is lytic. What is the primary goal of orthopedic stabilization in this setting?', '["Achieving a biologic union of the fracture site without cement", "Delaying surgery until radiation therapy is completed", "Preventing pulmonary metastasis", "Immediate pain relief, early mobilization, and restoration of function", "Curative resection of the tumor with wide margins"]'::jsonb, 3, 'The treatment of metastatic pathologic fractures is generally palliative. The goals are to provide immediate mechanical stability (often using intramedullary nails and cement), relieve pain, and allow early weight-bearing and functional independence.'),
    (v_topic_id, 'A 42-year-old patient presents with a slowly growing, deep, painless mass in the popliteal fossa. MRI shows a heterogeneous mass near the knee joint, but not within the joint capsule. Biopsy confirms a soft tissue sarcoma. Genetic testing reveals a t(X;18) chromosomal translocation. What is the diagnosis?', '["Undifferentiated pleomorphic sarcoma", "Clear cell sarcoma", "Liposarcoma", "Synovial Sarcoma", "Rhabdomyosarcoma"]'::jsonb, 3, 'Despite its name, Synovial Sarcoma rarely arises from the actual synovium of the joint, but typically occurs near large joints (e.g., the knee) in young adults. It is strongly associated with the t(X;18) translocation, which creates the SS18-SSX fusion gene.'),
    (v_topic_id, 'A 38-year-old patient presents with a slowly growing, deep, painless mass in the popliteal fossa. MRI shows a heterogeneous mass near the knee joint, but not within the joint capsule. Biopsy confirms a soft tissue sarcoma. Genetic testing reveals a t(X;18) chromosomal translocation. What is the diagnosis?', '["Clear cell sarcoma", "Synovial Sarcoma", "Rhabdomyosarcoma", "Undifferentiated pleomorphic sarcoma", "Liposarcoma"]'::jsonb, 1, 'Despite its name, Synovial Sarcoma rarely arises from the actual synovium of the joint, but typically occurs near large joints (e.g., the knee) in young adults. It is strongly associated with the t(X;18) translocation, which creates the SS18-SSX fusion gene.'),
